CREATE TABLE IF NOT EXISTS asset_risk_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE, model text NOT NULL DEFAULT 'OV-RISK-V1', overall_score numeric(6,2), risk_level text NOT NULL DEFAULT 'unassessed', factors jsonb NOT NULL DEFAULT '{}'::jsonb, mitigations jsonb NOT NULL DEFAULT '[]'::jsonb, assessed_at timestamptz NOT NULL DEFAULT now());